import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../../../app_config.dart';
import '../../../../models/keys/wallet_recovery_material.dart';
import '../../../../providers/providers.dart';
import '../../../../services/wallet_recovery_service.dart';
import '../../../../themes/stack_colors.dart';
import '../../../../utilities/text_styles.dart';
import '../../../../widgets/background.dart';
import '../../../../widgets/custom_buttons/app_bar_icon_button.dart';
import '../../../../widgets/rounded_container.dart';
import 'delete_view_only_wallet_keys_view.dart';
import 'delete_wallet_recovery_phrase_view.dart';

class DeleteWalletWarningView extends ConsumerWidget {
  const DeleteWalletWarningView({super.key, required this.walletId});

  static const String routeName = "/deleteWalletWarning";

  final String walletId;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    return Background(
      child: Scaffold(
        backgroundColor: Theme.of(context).extension<StackColors>()!.background,
        appBar: AppBar(
          leading: AppBarBackButton(
            onPressed: () {
              Navigator.of(context).pop();
            },
          ),
        ),
        body: SafeArea(
          child: Padding(
            padding: const EdgeInsets.only(top: 12, left: 16, right: 16),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                const SizedBox(height: 32),
                Center(
                  child: Text(
                    "Attention!",
                    style: STextStyles.pageTitleH1(context),
                  ),
                ),
                const SizedBox(height: 16),
                RoundedContainer(
                  color: Theme.of(
                    context,
                  ).extension<StackColors>()!.warningBackground,
                  child: Text(
                    "You are going to permanently delete your wallet.\n\n"
                    "If you delete your wallet, the only way you can have access"
                    " to your funds is by using your backup key.\n\n"
                    "${AppConfig.appName} does not keep nor is able to restore "
                    "your backup key or your wallet.\n\nPLEASE SAVE YOUR BACKUP KEY.",
                    style: STextStyles.baseXS(context).copyWith(
                      color: Theme.of(
                        context,
                      ).extension<StackColors>()!.warningForeground,
                    ),
                  ),
                ),
                const Spacer(),
                TextButton(
                  style: Theme.of(context)
                      .extension<StackColors>()!
                      .getSecondaryEnabledButtonStyle(context),
                  onPressed: () {
                    Navigator.pop(context);
                  },
                  child: Text(
                    "Cancel",
                    style: STextStyles.button(context).copyWith(
                      color: Theme.of(
                        context,
                      ).extension<StackColors>()!.accentColorDark,
                    ),
                  ),
                ),
                const SizedBox(height: 12),
                TextButton(
                  style: Theme.of(context)
                      .extension<StackColors>()!
                      .getPrimaryEnabledButtonStyle(context),
                  onPressed: () async {
                    final wallet = ref.read(pWallets).getWallet(walletId);
                    final recoveryMaterial =
                        await WalletRecoveryService.getMaterial(wallet);
                    if (context.mounted) {
                      if (recoveryMaterial
                          case final ViewOnlyWalletRecoveryMaterial data) {
                        await Navigator.of(context).pushNamed(
                          DeleteViewOnlyWalletKeysView.routeName,
                          arguments: (walletId: walletId, data: data.keyData),
                        );
                      } else {
                        await Navigator.of(context).pushNamed(
                          DeleteWalletRecoveryPhraseView.routeName,
                          arguments: recoveryMaterial,
                        );
                      }
                    }
                  },
                  child: Text(
                    "View Backup Key",
                    style: STextStyles.button(context),
                  ),
                ),
                const SizedBox(height: 16),
              ],
            ),
          ),
        ),
      ),
    );
  }
}
